// Phase 41k: stroke order from KanjiVG (CC BY-SA 3.0, ADR 015), generated by scripts/kanjivg.ts into its own file
// so the share-alike licence covers only strokes.json.
import { readFileSync } from 'node:fs';

const read = (f: string) => JSON.parse(readFileSync(new URL(f, import.meta.url), 'utf8')) as unknown;
const kanji = read('kanji.json') as { char: string; strokes: number }[];
const strokes = read('strokes.json') as { source: string; license: string; items: Record<string, string[]> };

describe('strokes.json', () => {
  it('credits KanjiVG and its licence', () => {
    expect(strokes.source).toMatch(/KanjiVG/);
    expect(strokes.license).toBe('CC BY-SA 3.0');
  });

  it('has every kanji in kanji.json and nothing else', () => {
    expect(Object.keys(strokes.items).sort()).toEqual(kanji.map((k) => k.char).sort());
  });

  it('gives each kanji its KANJIDIC stroke count, every stroke an SVG path', () => {
    const off = kanji.filter((k) => strokes.items[k.char]?.length !== k.strokes).map((k) => `${k.char} ${strokes.items[k.char]?.length} ≠ ${k.strokes}`);
    expect(off).toEqual([]);
    const bad = Object.entries(strokes.items).filter(([, d]) => !d.every((p) => /^[Mm][-\d.,\s]+[CcSsLlZzMmHhVv\d.,\s-]*$/.test(p)));
    expect(bad).toEqual([]);
  });
});
